import React from 'react';
import ReactDOM from 'react-dom';
import '@alifd/next/dist/next.css';
import { Table } from '@alifd/next';

class App extends React.Component {
  state = { widths: { id: 120, name: 200 } };

  onResizeChange = (dataIndex, diff) => {
    this.setState(prevState => {
      const widths = { ...prevState.widths };
      widths[dataIndex] = widths[dataIndex] + diff;
      return { widths };
    });
  };

  onFilter = filterParams => {
    console.log('filter', filterParams);
  };

  render() {
    const dataSource = Array.from({ length: 20 }).map((_, i) => ({
      id: i,
      name: `Item ${i}`,
      time: 2000 + i
    }));

    return (
      <Table
        dataSource={dataSource}
        fixedHeader
        maxBodyHeight={240}
        onResizeChange={this.onResizeChange}
        onFilter={this.onFilter}
      >
        <Table.Column
          title="ID"
          dataIndex="id"
          width={this.state.widths.id}
          resizable
          filters={[{ label: 'Even', value: 'even' }]}
          filterMode="single"
        />
        <Table.Column
          title="Name"
          dataIndex="name"
          width={this.state.widths.name}
          resizable
        />
        <Table.Column
          title="Time"
          dataIndex="time"
          width={200}
        />
      </Table>
    );
  }
}

ReactDOM.render(<App />, mountNode);
